362→// StartSession starts an interactive session and registers it for pane
363→// capture in artifacts. Returns nil if the agent does not support interactive
364→// mode. The session is closed automatically during test cleanup.
365→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
366→	t.Helper()
367→	session, err := s.Agent.StartSession(ctx, s.Dir)
368→	if err != nil {
369→		t.Fatalf("start session: %v", err)
370→	}
371→	if session == nil {
372→		return nil
373→	}
374→	s.session = session
