423→// Git runs a git command in the given directory and fails the test if it
424→// returns a non-zero exit code.
425→func Git(t *testing.T, dir string, args ...string) {
426→	t.Helper()
427→
428→	cmd := exec.Command("git", args...)
429→	if dir != "" {
430→		cmd.Dir = dir
431→	}
432→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
433→
434→	out, err := cmd.CombinedOutput()
435→	if err != nil {
436→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
437→	}
438→}
