440→// GitOutput runs a git command in the given directory, returns its trimmed
441→// stdout, and fails the test on error.
442→func GitOutput(t *testing.T, dir string, args ...string) string {
443→	t.Helper()
444→
445→	cmd := exec.Command("git", args...)
446→	if dir != "" {
447→		cmd.Dir = dir
448→	}
449→
450→	out, err := cmd.Output()
451→	if err != nil {
452→		var stderr string
453→		ee := &exec.ExitError{}
454→		if errors.As(err, &ee) {
455→			stderr = string(ee.Stderr)
456→		}
457→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
458→	}
459→
460→	return strings.TrimSpace(string(out))
461→}
