463→// NewCheckpointCommits returns the SHAs of commits added to the
464→// entire/checkpoints/v1 branch since the test was set up, oldest first.
465→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
466→	t.Helper()
467→
468→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
469→	if log == "" {
470→		return nil
471→	}
