562→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
563→// the initial commit. Returns the bare repo path.
564→func SetupBareRemote(t *testing.T, s *RepoState) string {
565→	t.Helper()
566→
567→	var bareDir string
568→	if os.Getenv("E2E_KEEP_REPOS") != "" {
569→		var err error
570→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
571→		if err != nil {
572→			t.Fatalf("create bare remote dir: %v", err)
573→		}
574→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
575→	} else {
576→		bareDir = t.TempDir()
577→	}
578→
579→	Git(t, bareDir, "init", "--bare")
580→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
581→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
582→	return bareDir
