378→// WaitFor waits for a pattern in the interactive session's pane and logs the
379→// pane content to ConsoleLog after the wait completes (success or failure).
380→func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
381→	t.Helper()
382→	content, err := session.WaitFor(pattern, timeout)
383→	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
384→	if err != nil {
385→		t.Fatalf("WaitFor(%q): %v", pattern, err)
386→	}
387→}
