389→// Send sends input to an interactive session and logs it to ConsoleLog.
390→// Fails the test on error.
391→func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
392→	t.Helper()
393→	s.ConsoleLog.WriteString("> send: " + input + "\n")
394→	if err := session.Send(input); err != nil {
395→		t.Fatalf("send failed: %v", err)
396→	}
397→}
