399→// PatchSettings merges extra keys into .entire/settings.json.
400→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
401→	t.Helper()
402→	path := filepath.Join(dir, ".entire", "settings.json")
403→	data, err := os.ReadFile(path)
404→	if err != nil {
405→		t.Fatalf("read settings: %v", err)
406→	}
407→	var settings map[string]any
408→	if err := json.Unmarshal(data, &settings); err != nil {
409→		t.Fatalf("parse settings: %v", err)
410→	}
411→	for k, v := range extra {
412→		settings[k] = v
