 53→func (f *FactoryAIDroidAgent) IsPreview() bool { return true }
 54→
 55→// ProtectedDirs returns directories that Factory AI Droid uses for config/state.
 56→func (f *FactoryAIDroidAgent) ProtectedDirs() []string { return []string{".factory"} }
 57→
 58→// DetectPresence checks if Factory AI Droid is configured in the repository.
 59→func (f *FactoryAIDroidAgent) DetectPresence(ctx context.Context) (bool, error) {
 60→	repoRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		repoRoot = "."
 63→	}
 64→	if _, err := os.Stat(filepath.Join(repoRoot, ".factory")); err == nil {
 65→		return true, nil
 66→	}
 67→	return false, nil
 68→}
