 24→// WriteHookResponse outputs the hook response as plain text to stdout.
 25→// Factory AI Droid does not parse the JSON systemMessage protocol,
 26→// so we write plain text that it displays directly in the terminal.
 27→func (f *FactoryAIDroidAgent) WriteHookResponse(message string) error {
 28→	if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
 29→		return fmt.Errorf("failed to write hook response: %w", err)
 30→	}
 31→	return nil
 32→}
 33→
 34→// HookNames returns the hook verbs Factory AI Droid supports.
 35→// These become subcommands: entire hooks factoryai-droid <verb>
 36→func (f *FactoryAIDroidAgent) HookNames() []string {
 37→	return []string{
 38→		HookNameSessionStart,
 39→		HookNameSessionEnd,
 40→		HookNameStop,
 41→		HookNameUserPromptSubmit,
 42→		HookNamePreToolUse,
 43→		HookNamePostToolUse,
 44→		HookNameSubagentStop,
 45→		HookNamePreCompact,
 46→		HookNameNotification,
 47→	}
 48→}
 49→
