// --- Prompt Parsing ---

type action struct {
	kind    string // "create", "modify", "delete", "commit"
	path    string
	content string
}

var (
	// "create a [markdown|text] file at <path>"
	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)([^\s,]+)`)
	// "create N files: <path> about <topic>, <path> about <topic>"
	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:four|three|two|\d+)\s+(?:markdown\s+)?files?:?\s+(.+)`)
	// "modify <path>"
	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
	// "modify these N files: <path> should ..."
	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+these\s+(?:three|four|two|\d+)\s+files?:?\s+(.+)`)
	// "delete <path>"
	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+)`)
	// "commit" anywhere in the prompt
	commitRe = regexp.MustCompile(`(?i)\b(?:then\s+)?commit\b`)
	// Individual file in multi-create: "docs/a.md about apples"
	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+(?:about\s+|with\s+|containing\s+)?([^,]+)`)
	// Individual file in multi-modify: "src/model.go should define ..."
	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+should\s+(.+?)(?:,|$)`)
)

func parsePrompt(prompt string) []action {
	var actions []action

	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
		for _, item := range items {
			actions = append(actions, action{
				kind:    "modify",
				path:    item[1],
				content: "// " + strings.TrimSpace(item[2]) + "\n",
			})
		}
		// Also check for files mentioned outside the "should" pattern
		if len(actions) == 0 {
			// Fallback: extract any file paths
			fileRe := regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
			for _, fm := range fileRe.FindAllStringSubmatch(m[1], -1) {
				actions = append(actions, action{
					kind:    "modify",
					path:    fm[1],
					content: "// Modified by fake agent\n",
				})
			}
		}
	}

	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
	if len(actions) == 0 {
		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
			for _, item := range items {
				actions = append(actions, action{
					kind:    "create",
					path:    item[1],
					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
				})
			}
		}
	}

	// Single file create
	if len(actions) == 0 {
		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
			topic := extractTopic(prompt)
			actions = append(actions, action{
				kind:    "create",
				path:    m[1],
				content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", topic, topic),
			})
		}
	}

	// Single file modify
	if len(actions) == 0 {
		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
			actions = append(actions, action{
				kind:    "modify",
				path:    m[1],
				content: "// Modified by fake agent\n",
			})
		}
	}

	// Delete
	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
		actions = append(actions, action{kind: "delete", path: m[1]})
	}

	// Commit (after other actions)
	if commitRe.MatchString(prompt) {
		actions = append(actions, action{kind: "commit"})
	}

	return actions
}

func extractTopic(prompt string) string {
	// "about the colour red" → "the colour red"
	re := regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
	if m := re.FindStringSubmatch(prompt); m != nil {
		return strings.TrimSpace(m[1])
	}
	return "the topic"
}

func executeActions(dir string, actions []action) {
	for _, a := range actions {
		switch a.kind {
		case "create":
			createFile(dir, a.path, a.content)
		case "modify":
			modifyFile(dir, a.path, a.content)
		case "delete":
			deleteFile(dir, a.path)
		case "commit":
			gitCommit(dir)
		}
	}
}

func createFile(dir, path, content string) {
	abs := filepath.Join(dir, path)
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		fmt.Fprintf(os.Stderr, "mkdir %s: %v\n", filepath.Dir(abs), err)
		return
	}
	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
	}
}

func modifyFile(dir, path, appendContent string) {
	abs := filepath.Join(dir, path)
	existing, _ := os.ReadFile(abs)
	content := string(existing) + "\n" + appendContent
	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
	}
}

func deleteFile(dir, path string) {
	abs := filepath.Join(dir, path)
	if err := os.Remove(abs); err != nil {
		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
	}
}

func gitCommit(dir string) {
	gitRun(dir, "add", ".")
	gitRun(dir, "commit", "-m", "Fake agent commit")
}

func gitRun(dir string, args ...string) {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "git %s: %v\n", strings.Join(args, " "), err)
	}
}

// --- Hook Firing ---

func fireHook(dir, hookName string, payload interface{}) {
	data, err := json.Marshal(payload)
	if err != nil {
		fmt.Fprintf(os.Stderr, "marshal hook payload: %v\n", err)
		return
	}

	cmd := exec.Command("entire", "hooks", "fake", hookName)
	cmd.Dir = dir
	cmd.Stdin = bytes.NewReader(data)
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
	// Capture output but don't show it — hooks may output banners
	out, err := cmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(os.Stderr, "hook %s failed: %v\n%s\n", hookName, err, out)
	}
}

// --- Transcript ---

func setupTranscript(dir, sessionID string) string {
	home, err := os.UserHomeDir()
	if err != nil {
		fatal("home dir: %v", err)
	}
	transcriptDir := filepath.Join(home, ".fakeagent", "sessions")
	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
		fatal("mkdir transcript dir: %v", err)
	}
	path := filepath.Join(transcriptDir, sessionID+".jsonl")
	// Create empty file
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		fatal("create transcript: %v", err)
	}
	return path
}

func appendTranscript(path, role, content string) {
	entry := map[string]interface{}{
		"type":      role,
		"timestamp": time.Now().Format(time.RFC3339),
		"message":   content,
	}
	data, _ := json.Marshal(entry)
	data = append(data, '\n')

	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)
	if err != nil {
		return
	}
	defer f.Close()
	f.Write(data) //nolint:errcheck
}

func fatal(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "fakeagent: "+format+"\n", args...)
	os.Exit(1)
}

