// --- Prompt Parsing ---

type action struct {
	kind    string // "create", "modify", "delete", "commit"
	path    string
	content string
}

var (
	// "create a [markdown|text] file at <path>"
	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)([^\s,]+)`)
	// "create N files: <path> about <topic>, <path> about <topic>"
	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:four|three|two|\d+)\s+(?:markdown\s+)?files?:?\s+(.+)`)
	// "modify <path>"
	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
	// "modify these N files: <path> should ..."
	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+these\s+(?:three|four|two|\d+)\s+files?:?\s+(.+)`)
	// "delete <path>"
	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+)`)
	// "commit" anywhere in the prompt
	commitRe = regexp.MustCompile(`(?i)\b(?:then\s+)?commit\b`)
	// Individual file in multi-create: "docs/a.md about apples"
	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+(?:about\s+|with\s+|containing\s+)?([^,]+)`)
	// Individual file in multi-modify: "src/model.go should define ..."
	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+should\s+(.+?)(?:,|$)`)
)

func parsePrompt(prompt string) []action {
	var actions []action

	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
		for _, item := range items {
			actions = append(actions, action{
				kind:    "modify",
				path:    item[1],
				content: "// " + strings.TrimSpace(item[2]) + "\n",
			})
		}
		// Also check for files mentioned outside the "should" pattern
		if len(actions) == 0 {
			// Fallback: extract any file paths
			fileRe := regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
			for _, fm := range fileRe.FindAllStringSubmatch(m[1], -1) {
				actions = append(actions, action{
					kind:    "modify",
					path:    fm[1],
					content: "// Modified by fake agent\n",
				})
			}
		}
	}

	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
	if len(actions) == 0 {
		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
			for _, item := range items {
				actions = append(actions, action{
					kind:    "create",
					path:    item[1],
					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
				})
			}
		}
	}

	// Single file create
	if len(actions) == 0 {
		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
			topic := extractTopic(prompt)
			actions = append(actions, action{
				kind:    "create",
				path:    m[1],
				content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", topic, topic),
			})
		}
	}

	// Single file modify
	if len(actions) == 0 {
		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
			actions = append(actions, action{
				kind:    "modify",
				path:    m[1],
				content: "// Modified by fake agent\n",
			})
		}
	}

	// Delete
	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
		actions = append(actions, action{kind: "delete", path: m[1]})
	}

	// Commit (after other actions)
	if commitRe.MatchString(prompt) {
		actions = append(actions, action{kind: "commit"})
	}

	return actions
}

func extractTopic(prompt string) string {
	// "about the colour red" → "the colour red"
	re := regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
	if m := re.FindStringSubmatch(prompt); m != nil {
		return strings.TrimSpace(m[1])

