 69→// --- Legacy Session Methods ---
 70→
 71→func (v *Agent) GetSessionID(input *agent.HookInput) string { return input.SessionID }
 72→
 73→func (v *Agent) GetSessionDir(_ string) (string, error) {
 74→	if override := os.Getenv("ENTIRE_TEST_VOGON_PROJECT_DIR"); override != "" {
 75→		return override, nil
 76→	}
 77→	homeDir, err := os.UserHomeDir()
 78→	if err != nil {
 79→		return "", fmt.Errorf("get home dir: %w", err)
 80→	}
 81→	return filepath.Join(homeDir, ".vogon", "sessions"), nil
 82→}
 83→
 84→func (v *Agent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 85→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 86→}
 87→
 88→func (v *Agent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 89→	if input.SessionRef == "" {
 90→		return nil, errors.New("session reference (transcript path) is required")
 91→	}
 92→	data, err := os.ReadFile(input.SessionRef)
 93→	if err != nil {
 94→		if os.IsNotExist(err) {
 95→			// Transcript may not exist yet — return empty session
 96→			return &agent.AgentSession{
 97→				SessionID:  input.SessionID,
 98→				AgentName:  v.Name(),
 99→				SessionRef: input.SessionRef,
100→			}, nil
101→		}
102→		return nil, fmt.Errorf("read transcript: %w", err)
103→	}
104→	return &agent.AgentSession{
105→		SessionID:  input.SessionID,
106→		AgentName:  v.Name(),
107→		SessionRef: input.SessionRef,
108→		NativeData: data,
109→	}, nil
110→}
111→
112→func (v *Agent) WriteSession(_ context.Context, session *agent.AgentSession) error {
113→	if session == nil {
114→		return errors.New("session is nil")
115→	}
116→	if session.SessionRef == "" {
117→		return errors.New("session reference is required")
118→	}
119→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
120→		return fmt.Errorf("create session dir: %w", err)
121→	}
122→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
123→		return fmt.Errorf("write session: %w", err)
124→	}
125→	return nil
126→}
127→
128→func (v *Agent) FormatResumeCommand(sessionID string) string {
129→	return "vogon --session-id " + sessionID
130→}
