  1→// vogon is a deterministic agent binary for E2E canary tests.
  2→// It parses simple prompt instructions, performs file operations, fires
  3→// lifecycle hooks via `entire hooks vogon <verb>`, and writes a minimal
  4→// JSONL transcript. No API calls are made.
  5→//
  6→// Named after the Vogons from The Hitchhiker's Guide to the Galaxy —
  7→// bureaucratic, procedural, and deterministic to a fault.
  8→//
  9→// Usage:
 10→//
 11→//	vogon -p <prompt>   # Headless (single-turn) mode
 12→//	vogon               # Interactive (multi-turn) mode
 13→package main
 14→
 15→import (
 16→	"bufio"
 17→	"bytes"
 18→	"encoding/json"
 19→	"fmt"
 20→	"os"
 21→	"os/exec"
 22→	"path/filepath"
 23→	"regexp"
 24→	"strings"
 25→	"time"
 26→
 27→	"github.com/google/uuid"
 28→)
 29→
 30→func main() {
 31→	prompt := ""
 32→	for i := 1; i < len(os.Args); i++ {
 33→		if os.Args[i] == "-p" && i+1 < len(os.Args) {
 34→			prompt = os.Args[i+1]
 35→			i++
 36→		}
 37→	}
 38→
 39→	dir, err := os.Getwd() //nolint:forbidigo // Standalone binary, not part of CLI — CWD is the repo dir
 40→	if err != nil {
 41→		fatal("getwd: %v", err)
 42→	}
 43→
 44→	sessionID := uuid.New().String()
 45→	transcriptPath := setupTranscript(dir, sessionID)
 46→
 47→	fireHook(dir, "session-start", map[string]string{
 48→		"session_id":      sessionID,
 49→		"transcript_path": transcriptPath,
 50→	})
 51→
 52→	if prompt != "" {
 53→		// Headless mode: single prompt
 54→		runTurn(dir, sessionID, transcriptPath, prompt)
 55→	} else {
 56→		// Interactive mode: read prompts from stdin
 57→		fmt.Fprint(os.Stdout, "> ")
 58→		scanner := bufio.NewScanner(os.Stdin)
 59→		for scanner.Scan() {
 60→			line := strings.TrimSpace(scanner.Text())
 61→			if line == "" || line == "exit" || line == "quit" {
 62→				break
 63→			}
 64→			// Give tmux's Send() time to capture the echoed-input state
 65→			// before we produce any output. Send polls every 200ms; without
 66→			// this pause, vogon output appears in the same capture window
 67→			// as the echo, causing stableAtSend to include final output and
 68→			// preventing WaitFor's contentChanged detection.
 69→			time.Sleep(700 * time.Millisecond)
 70→			fmt.Fprintln(os.Stdout, "Working...")
 71→			runTurn(dir, sessionID, transcriptPath, line)
 72→			fmt.Fprint(os.Stdout, "> ")
 73→		}
 74→	}
 75→
 76→	fireHook(dir, "session-end", map[string]string{
 77→		"session_id":      sessionID,
 78→		"transcript_path": transcriptPath,
 79→	})
 80→}
 81→
 82→func runTurn(dir, sessionID, transcriptPath, prompt string) {
 83→	fireHook(dir, "user-prompt-submit", map[string]any{
 84→		"session_id":      sessionID,
 85→		"transcript_path": transcriptPath,
 86→		"prompt":          prompt,
 87→	})
 88→
 89→	appendTranscript(transcriptPath, "user", prompt)
 90→
 91→	actions := parsePrompt(prompt)
 92→	executeActions(dir, actions)
 93→
 94→	appendTranscript(transcriptPath, "assistant", fmt.Sprintf("Done. Executed %d actions.", len(actions)))
 95→	fmt.Fprintf(os.Stdout, "Done. Executed %d actions.\n", len(actions))
 96→
 97→	fireHook(dir, "stop", map[string]string{
 98→		"session_id":      sessionID,
 99→		"transcript_path": transcriptPath,
100→	})
101→}
102→
103→// --- Prompt Parsing ---
104→
105→type action struct {
106→	kind    string // "create", "modify", "delete", "commit"
107→	path    string
108→	content string
109→}
110→
111→var (
112→	// "create a [single|new|...] [markdown|text] file [at|called] <path>"
113→	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:\w+\s+)*?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
114→	// "create N files: <path> about <topic>, <path> about <topic>"
115→	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:\w+\s+)*?(?:four|three|two|\d+)\s+(?:\w+\s+)*?(?:markdown\s+)?files?:?\s+(.+)`)
116→	// "modify <path>"
117→	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
118→	// "modify [these] N [existing] files[:]"
119→	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+(?:these\s+)?(?:three|four|two|\d+)\s+(?:\w+\s+)*?files?[.:]\s*(.+)`)
120→	// "add ... to <path>" (e.g. "add another stanza to poem.txt")
121→	addToFileRe = regexp.MustCompile(`(?i)add\s+(?:another\s+|a\s+|some\s+)?\w+\s+to\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
122→	// "delete <path>"
123→	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
124→	// "commit" anywhere in the prompt, but not "do not commit" / "don't commit"
125→	commitRe = regexp.MustCompile(`(?i)(?:then\s+|now\s+)?(?:git\s+)?commit\b`)
126→	// Negative: "do not commit" / "don't commit" with optional object, at sentence boundary
127→	// Matches: "Do not commit.", "Do not commit the file.", "Do not commit them,"
128→	// Does NOT match: "Do not commit any other files" (different intent)
129→	noCommitRe = regexp.MustCompile(`(?i)(?:do\s+not|don'?t)\s+commit(?:\s+(?:it|them|the\s+\w+))?(?:\.|,|$)`)
130→	// "commit each file separately" — interleave create+commit
131→	commitSeparatelyRe = regexp.MustCompile(`(?i)commit\s+each\s+file\s+separately`)
132→	// Individual file in multi-create: "docs/a.md about apples"
133→	// Topic capture stops at comma, "and", period followed by space+uppercase, or end
134→	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+(?:about\s+|with\s+|containing\s+)?(.+?)(?:,\s*|\s+and\s+|\.\s+[A-Z]|\.\s*$)`)
135→	// Individual file in multi-modify: "src/model.go should define ..."
136→	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))\s+should\s+(.+?)(?:,|$)`)
137→	// "In src/a.go, add ..." pattern for multi-modify
138→	inFileRe = regexp.MustCompile(`[Ii]n\s+([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs|toml|yaml|json))`)
139→	// Inline content: "with content 'package main; func Foo() {}'"
140→	inlineContentRe = regexp.MustCompile(`(?i)with\s+content\s+['"]([^'"]+)['"]`)
141→	// Numbered steps: "(1) ... (2) ... (3) ..."
142→	numberedStepRe = regexp.MustCompile(`\(\d+\)\s+`)
143→	// Explicit git command: "Run: git add ... && git commit -m '...'"
144→	explicitGitRe = regexp.MustCompile(`(?i)run:?\s+git\s+add\s+.+(?:&&\s*git\s+commit|;\s*git\s+commit)`)
145→)
146→
147→func parsePrompt(prompt string) []action {
148→	// Check for numbered-step prompts — parse each step independently to
149→	// preserve ordering (e.g., create, commit, then create more).
150→	if numberedStepRe.MatchString(prompt) {
151→		return parseNumberedSteps(prompt)
152→	}
153→	var actions []action
154→
155→	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
156→	// Also matches: "Modify two existing files. In src/a.go, add ..."
157→	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
158→		// Try "should" pattern first
159→		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
160→		for _, item := range items {
161→			actions = append(actions, action{
162→				kind:    "modify",
163→				path:    item[1],
164→				content: "// " + strings.TrimSpace(item[2]) + "\n",
165→			})
166→		}
167→		// Try "In <path>" pattern as fallback
168→		if len(actions) == 0 {
169→			for _, item := range inFileRe.FindAllStringSubmatch(m[1], -1) {
170→				actions = append(actions, action{
171→					kind:    "modify",
172→					path:    item[1],
173→					content: "// Modified by vogon agent\n",
174→				})
175→			}
176→		}
177→		// Last resort: extract any file paths
178→		if len(actions) == 0 {
179→			fileRe := regexp.MustCompile(`([^\s,]+\.(?:go|md|txt|js|ts|py|rb|rs))`)
180→			for _, fm := range fileRe.FindAllStringSubmatch(m[1], -1) {
181→				actions = append(actions, action{
182→					kind:    "modify",
183→					path:    fm[1],
184→					content: "// Modified by vogon agent\n",
185→				})
186→			}
187→		}
188→	}
189→
190→	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
191→	if len(actions) == 0 || hasModifyOnly(actions) {
192→		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
193→			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
194→			for _, item := range items {
195→				actions = append(actions, action{
196→					kind:    "create",
197→					path:    item[1],
198→					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
199→				})
200→			}
201→		}
202→	}
203→
204→	// Single file create — also runs if we only have modifies (combined prompts)
205→	if !hasCreate(actions) {
206→		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
207→			content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", extractTopic(prompt), extractTopic(prompt))
208→			if ic := inlineContentRe.FindStringSubmatch(prompt); ic != nil {
209→				content = ic[1] + "\n"
210→			}
211→			actions = append(actions, action{
212→				kind:    "create",
213→				path:    m[1],
214→				content: content,
215→			})
216→		}
217→	}
218→
219→	// Single file modify — also runs if we only have creates (combined prompts)
220→	if !hasModify(actions) {
221→		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
222→			actions = append(actions, action{
223→				kind:    "modify",
224→				path:    m[1],
225→				content: "// Modified by vogon agent\n",
226→			})
227→		}
228→	}
229→
230→	// "add ... to <path>" as modify (e.g. "add another stanza to poem.txt")
231→	if !hasModify(actions) {
232→		if m := addToFileRe.FindStringSubmatch(prompt); m != nil {
233→			actions = append(actions, action{
234→				kind:    "modify",
235→				path:    m[1],
236→				content: "// Modified by vogon agent\n",
237→			})
238→		}
239→	}
240→
241→	// Delete
242→	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
243→		actions = append(actions, action{kind: "delete", path: m[1]})
244→	}
245→
246→	// Commit: check for "commit each file separately" (interleaved) vs normal.
247→	// Skip if prompt contains "do not commit" / "don't commit".
248→	if !noCommitRe.MatchString(prompt) {
249→		if commitSeparatelyRe.MatchString(prompt) {
250→			actions = interleaveCommits(actions)
251→		} else if commitRe.MatchString(prompt) {
252→			actions = append(actions, action{kind: "commit"})
253→		}
254→	}
255→
256→	return actions
257→}
258→
259→// parseNumberedSteps splits "(1) ... (2) ... (3) ..." prompts into individual
260→// steps and parses each one, preserving ordering. This handles prompts like:
261→// "(1) Create file A. (2) Create file B. (3) git commit. (4) Create file C."
262→func parseNumberedSteps(prompt string) []action {
263→	// Split on numbered markers: "(1) ", "(2) ", etc.
264→	indices := numberedStepRe.FindAllStringIndex(prompt, -1)
265→	if len(indices) == 0 {
266→		return nil
267→	}
268→
269→	var steps []string
270→	for i, idx := range indices {
271→		start := idx[1] // after the "(N) " marker
272→		var end int
273→		if i+1 < len(indices) {
274→			end = indices[i+1][0]
275→		} else {
276→			end = len(prompt)
277→		}
278→		step := strings.TrimSpace(prompt[start:end])
279→		if step != "" {
280→			steps = append(steps, step)
281→		}
282→	}
283→
284→	var actions []action
285→	for _, step := range steps {
286→		// Explicit git command: "Run: git add ... && git commit ..."
287→		if explicitGitRe.MatchString(step) {
288→			actions = append(actions, action{kind: "commit"})
289→			continue
290→		}
291→
292→		// Create file with optional inline content
293→		if m := createFileRe.FindStringSubmatch(step); m != nil {
294→			content := fmt.Sprintf("# %s\n\nGenerated content.\n", m[1])
295→			if ic := inlineContentRe.FindStringSubmatch(step); ic != nil {
296→				content = ic[1] + "\n"
297→			}
298→			actions = append(actions, action{kind: "create", path: m[1], content: content})
299→			continue
300→		}
301→
302→		// Modify file
303→		if m := modifyFileRe.FindStringSubmatch(step); m != nil {
304→			actions = append(actions, action{kind: "modify", path: m[1], content: "// Modified by vogon agent\n"})
305→			continue
306→		}
307→
308→		// Delete file
309→		if m := deleteFileRe.FindStringSubmatch(step); m != nil {
310→			actions = append(actions, action{kind: "delete", path: m[1]})
311→			continue
312→		}
313→
314→		// Bare commit instruction
315→		if commitRe.MatchString(step) && !noCommitRe.MatchString(step) {
316→			actions = append(actions, action{kind: "commit"})
317→		}
318→	}
319→	return actions
320→}
321→
322→func hasCreate(actions []action) bool {
323→	for _, a := range actions {
324→		if a.kind == "create" {
325→			return true
326→		}
327→	}
328→	return false
329→}
330→
331→func hasModify(actions []action) bool {
332→	for _, a := range actions {
333→		if a.kind == "modify" {
334→			return true
335→		}
336→	}
337→	return false
338→}
339→
340→func hasModifyOnly(actions []action) bool {
341→	if len(actions) == 0 {
342→		return false
343→	}
344→	for _, a := range actions {
345→		if a.kind != "modify" {
346→			return false
347→		}
348→	}
349→	return true
350→}
351→
352→// interleaveCommits inserts a commit after each create/modify action.
353→func interleaveCommits(actions []action) []action {
354→	var result []action
355→	for _, a := range actions {
356→		result = append(result, a)
357→		if a.kind == "create" || a.kind == "modify" {
358→			result = append(result, action{kind: "commit"})
359→		}
360→	}
361→	return result
362→}
363→
364→func extractTopic(prompt string) string {
365→	// "about the colour red" → "the colour red"
366→	re := regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
367→	if m := re.FindStringSubmatch(prompt); m != nil {
368→		return strings.TrimSpace(m[1])
369→	}
370→	return "the topic"
371→}
372→
373→func executeActions(dir string, actions []action) {
374→	for _, a := range actions {
375→		switch a.kind {
376→		case "create":
377→			createFile(dir, a.path, a.content)
378→		case "modify":
379→			modifyFile(dir, a.path, a.content)
380→		case "delete":
381→			deleteFile(dir, a.path)
382→		case "commit":
383→			gitCommit(dir)
384→		}
385→	}
386→}
387→
388→func createFile(dir, path, content string) {
389→	abs := filepath.Join(dir, path)
390→	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
391→		fmt.Fprintf(os.Stderr, "mkdir %s: %v\n", filepath.Dir(abs), err)
392→		return
393→	}
394→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
395→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
396→	}
397→}
398→
399→func modifyFile(dir, path, appendContent string) {
400→	abs := filepath.Join(dir, path)
401→	existing, _ := os.ReadFile(abs)
402→	content := string(existing) + "\n" + appendContent
403→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
404→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
405→	}
406→}
407→
408→func deleteFile(dir, path string) {
409→	abs := filepath.Join(dir, path)
410→	if err := os.Remove(abs); err != nil {
411→		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
412→	}
413→}
414→
415→func gitCommit(dir string) {
416→	gitRun(dir, "add", ".")
417→	gitRun(dir, "commit", "-m", "Vogon agent commit")
418→}
419→
420→func gitRun(dir string, args ...string) {
421→	cmd := exec.Command("git", args...)
422→	cmd.Dir = dir
423→	cmd.Stdout = os.Stdout
424→	cmd.Stderr = os.Stderr
425→	// Signal that this is a non-interactive agent — git hooks should not
426→	// attempt TTY prompts. GIT_TERMINAL_PROMPT is the standard git env var
427→	// for this (same approach used by Factory AI Droid).
428→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
429→	if err := cmd.Run(); err != nil {
430→		fmt.Fprintf(os.Stderr, "git %s: %v\n", strings.Join(args, " "), err)
431→	}
432→}
433→
434→// --- Hook Firing ---
435→
436→func fireHook(dir, hookName string, payload any) {
437→	data, err := json.Marshal(payload)
438→	if err != nil {
439→		fmt.Fprintf(os.Stderr, "marshal hook payload: %v\n", err)
440→		return
441→	}
442→
443→	cmd := exec.Command("entire", "hooks", "vogon", hookName)
444→	cmd.Dir = dir
445→	cmd.Stdin = bytes.NewReader(data)
446→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
447→	// Capture output but don't show it — hooks may output banners
448→	out, err := cmd.CombinedOutput()
449→	if err != nil {
450→		fmt.Fprintf(os.Stderr, "hook %s failed: %v\n%s\n", hookName, err, out)
451→	}
452→}
453→
454→// --- Transcript ---
455→
456→func setupTranscript(_, sessionID string) string {
457→	home, err := os.UserHomeDir()
458→	if err != nil {
459→		fatal("home dir: %v", err)
460→	}
461→	transcriptDir := filepath.Join(home, ".vogon", "sessions")
462→	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
463→		fatal("mkdir transcript dir: %v", err)
464→	}
465→	path := filepath.Join(transcriptDir, sessionID+".jsonl")
466→	// Create empty file
467→	if err := os.WriteFile(path, nil, 0o644); err != nil {
468→		fatal("create transcript: %v", err)
469→	}
470→	return path
471→}
472→
473→type transcriptEntry struct {
474→	Type      string `json:"type"`
475→	Timestamp string `json:"timestamp"`
476→	Message   string `json:"message"`
477→}
478→
479→func appendTranscript(path, role, content string) {
480→	entry := transcriptEntry{
481→		Type:      role,
482→		Timestamp: time.Now().Format(time.RFC3339),
483→		Message:   content,
484→	}
485→	data, _ := json.Marshal(entry) //nolint:errchkjson // transcriptEntry has no unsafe types
486→	data = append(data, '\n')
487→
488→	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o644)
489→	if err != nil {
490→		return
491→	}
492→	defer f.Close()
493→	f.Write(data)
494→}
495→
496→func fatal(format string, args ...any) {
497→	fmt.Fprintf(os.Stderr, "vogon: "+format+"\n", args...)
498→	os.Exit(1)
499→}
