 96→// GetSessionDir returns the directory where Factory AI Droid stores session transcripts.
 97→// Path: ~/.factory/sessions/<sanitized-repo-path>/
 98→func (f *FactoryAIDroidAgent) GetSessionDir(repoPath string) (string, error) {
 99→	if override := os.Getenv("ENTIRE_TEST_DROID_PROJECT_DIR"); override != "" {
100→		return override, nil
101→	}
102→	homeDir, err := os.UserHomeDir()
103→	if err != nil {
104→		return "", fmt.Errorf("failed to get home directory: %w", err)
105→	}
