 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string   // stable content snapshot when Send was last called
 15→	cleanups     []func() // run on Close
 16→}
 17→
 18→// OnClose registers a function to run when the session is closed.
 19→func (s *TmuxSession) OnClose(fn func()) {
 20→	s.cleanups = append(s.cleanups, fn)
 21→}
 22→
 23→// NewTmuxSession creates a new tmux session running the given command in dir.
 24→// unsetEnv lists environment variable names to strip from the session.
 25→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 26→	s := &TmuxSession{name: name}
 27→
 28→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 29→	// Build a shell command string, prefixed with env -u for each var to strip.
 30→	// All arguments are shell-quoted to prevent injection or splitting.
 31→	var parts []string
 32→	for _, v := range unsetEnv {
 33→		parts = append(parts, "env", "-u", shellQuote(v))
 34→	}
 35→	parts = append(parts, shellQuote(command))
 36→	for _, a := range args {
 37→		parts = append(parts, shellQuote(a))
 38→	}
 39→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 40→
 41→	cmd := exec.Command("tmux", tmuxArgs...)
 42→	if out, err := cmd.CombinedOutput(); err != nil {
 43→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 44→	}
 45→	// Keep the pane around after the command exits so we can capture error output.
 46→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 47→	_ = setCmd.Run()
 48→	return s, nil
 49→}
 50→
 51→func (s *TmuxSession) Send(input string) error {
 52→	preSend := stableContent(s.Capture())
 53→	// Send text and Enter separately — Claude's TUI can swallow Enter
 54→	// if it arrives before the input handler finishes processing the text.
 55→	if err := s.SendKeys(input); err != nil {
 56→		return err
 57→	}
 58→	time.Sleep(200 * time.Millisecond)
 59→	if err := s.SendKeys("Enter"); err != nil {
 60→		return err
 61→	}
 62→
 63→	// Wait for the terminal to reflect the echoed input, then snapshot.
 64→	// This ensures WaitFor compares against post-echo content, preventing
 65→	// false matches on prompt characters (e.g. ❯) in the echoed input.
 66→	deadline := time.Now().Add(5 * time.Second)
 67→	for time.Now().Before(deadline) {
 68→		time.Sleep(200 * time.Millisecond)
 69→		current := stableContent(s.Capture())
 70→		if current != preSend {
 71→			s.stableAtSend = current
 72→			return nil
 73→		}
 74→	}
 75→	s.stableAtSend = stableContent(s.Capture())
 76→	return nil
 77→}
 78→
 79→// SendKeys sends raw tmux key names without appending Enter.
 80→func (s *TmuxSession) SendKeys(keys ...string) error {
 81→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 82→	cmd := exec.Command("tmux", args...)
 83→	out, err := cmd.CombinedOutput()
 84→	if err != nil {
 85→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 86→	}
 87→	return nil
 88→}
 89→
 90→const (
 91→	settleTime   = 2 * time.Second
 92→	pollInterval = 500 * time.Millisecond
 93→)
 94→
 95→// stableContent returns the content with the last few lines stripped,
 96→// so that TUI status bar updates don't prevent the settle timer.
 97→func stableContent(content string) string {
 98→	lines := strings.Split(content, "\n")
 99→	if len(lines) > 3 {
100→		lines = lines[:len(lines)-3]
101→	}
102→	return strings.Join(lines, "\n")
103→}
104→
105→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
106→	re, err := regexp.Compile(pattern)
107→	if err != nil {
108→		return "", fmt.Errorf("invalid pattern: %w", err)
109→	}
110→
111→	deadline := time.Now().Add(timeout)
112→	var matchedAt time.Time
113→	var lastStable string
114→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
115→
116→	for time.Now().Before(deadline) {
117→		content := s.Capture()
118→		stable := stableContent(content)
119→
120→		// Bail early if the process has exited and the pattern doesn't match.
121→		// remain-on-exit keeps the pane alive, so without this check we'd
122→		// poll a dead pane for the full timeout duration.
123→		if !re.MatchString(content) {
124→			if s.IsPaneDead() {
125→				return content, fmt.Errorf("process exited while waiting for %q\n--- pane content ---\n%s\n--- end pane content ---", pattern, content)
126→			}
127→			// Pattern lost — reset
128→			matchedAt = time.Time{}
129→			lastStable = ""
130→			time.Sleep(pollInterval)
131→			continue
132→		}
133→
134→		// Detect content change since Send was called
135→		if !contentChanged && stable != s.stableAtSend {
136→			contentChanged = true
137→		}
138→
139→		if stable != lastStable {
140→			// Pattern matches but content is still changing — reset settle timer
141→			matchedAt = time.Now()
142→			lastStable = stable
143→			time.Sleep(pollInterval)
144→			continue
145→		}
146→
147→		// Pattern matches and content hasn't changed since matchedAt.
148→		// Only settle if content changed at least once after Send
149→		// (prevents false settle on echoed input before agent starts).
150→		if contentChanged && time.Since(matchedAt) >= settleTime {
151→			return content, nil
152→		}
153→
154→		time.Sleep(pollInterval)
155→	}
156→	content := s.Capture()
157→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
158→}
159→
160→// IsPaneDead returns true if the process inside the tmux pane has exited.
161→// This relies on the remain-on-exit option being set (which NewTmuxSession does).
162→func (s *TmuxSession) IsPaneDead() bool {
163→	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
164→	out, err := cmd.Output()
165→	if err != nil {
166→		// If tmux itself fails (e.g. session/pane no longer exists),
167→		// treat it as dead so WaitFor doesn't poll until timeout.
168→		return true
169→	}
170→	return strings.TrimSpace(string(out)) == "1"
171→}
172→
173→func (s *TmuxSession) Capture() string {
174→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
175→	out, _ := cmd.Output()
176→	return strings.TrimRight(string(out), "\n")
177→}
178→
179→func (s *TmuxSession) Close() error {
180→	for _, fn := range s.cleanups {
181→		fn()
182→	}
183→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
184→	out, err := cmd.CombinedOutput()
185→	if err != nil {
186→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
187→	}
188→	return nil
189→}
190→
191→// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
192→func shellQuote(s string) string {
193→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
194→}
